using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text.Json;
using System.Security.Cryptography;

static class Checks {
 static string snapshot="";static nint window;static JsonElement current;
 static readonly List<string> passed=[];
 static double Now()=>Stopwatch.GetTimestamp()*1000.0/Stopwatch.Frequency;
 static JsonElement Read(){try{using var stream=new FileStream(snapshot,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);using var document=JsonDocument.Parse(stream);var root=document.RootElement;if(!root.TryGetProperty("endFrame",out var end)||end.GetUInt64()!=root.GetProperty("frames").GetUInt64())return default;return root.Clone();}catch(IOException){return default;}catch(JsonException){return default;}}
 static void Wait(Func<JsonElement,bool> predicate,string label,int timeout=30000){double end=Now()+timeout;while(true){current=Read();if(current.ValueKind==JsonValueKind.Object&&predicate(current)){passed.Add(label);return;}if(Now()>end)throw new TimeoutException(label);Thread.Sleep(15);}}
 static int Number(string key)=>current.GetProperty(key).GetInt32();
 static bool Flag(string key)=>current.GetProperty(key).GetBoolean();
