 static void Click(string name){Wait(_=>Widget(name) is JsonElement item&&item.GetProperty("visible").GetBoolean()&&item.GetProperty("enabled").GetBoolean(),"target: "+name);if(!Native.Foreground(window))throw new InvalidOperationException("Foreground lost");var w=Widget(name)!.Value;var point=new Native.Point{X=(int)(w.GetProperty("x").GetDouble()+w.GetProperty("w").GetDouble()/2),Y=(int)(w.GetProperty("y").GetDouble()+w.GetProperty("h").GetDouble()/2)};Native.ClientToScreen(window,ref point);Native.SetCursorPos(point.X,point.Y);Thread.Sleep(70);Native.SendInput(1,[new Native.Input{Mouse=new Native.MouseInput{Flags=2}}],Marshal.SizeOf<Native.Input>());Thread.Sleep(40);Native.SendInput(1,[new Native.Input{Mouse=new Native.MouseInput{Flags=4}}],Marshal.SizeOf<Native.Input>());Thread.Sleep(100);}
 [StructLayout(LayoutKind.Sequential)] struct KeyData {public ushort Vk,Scan;public uint Flags,Time;public nuint Extra;}
 [StructLayout(LayoutKind.Explicit,Size=40)]struct Input{[FieldOffset(0)]public uint Type;[FieldOffset(8)]public KeyData Key;}
 [DllImport("user32.dll",EntryPoint="SendInput")]static extern uint Send(uint count,Input[] input,int size);
 static void Key(ushort vk,bool up=false){if(Send(1,[new Input{Type=1,Key=new KeyData{Vk=vk,Flags=up?2u:0u}}],Marshal.SizeOf<Input>())!=1)throw new InvalidOperationException("Key input failed");Thread.Sleep(30);}
 static void Press(ushort vk){Key(vk);Key(vk,true);}
 static void Query(string value){Click("Filter synthetic rows");Key(0x11);Press(0x41);Key(0x11,true);Press(8);foreach(char ch in value){var input=new[]{new Input{Type=1,Key=new KeyData{Scan=ch,Flags=4}},new Input{Type=1,Key=new KeyData{Scan=ch,Flags=6}}};if(Send(2,input,Marshal.SizeOf<Input>())!=2)throw new InvalidOperationException("Unicode input failed");}Thread.Sleep(100);}
 static void Rows(int count,int tick,int? id=null)=>Wait(_=>Number("count")==count&&Number("tick")==tick&&(!id.HasValue||Number("firstId")==id),$"rows {count}/{tick}/{id}");
 static void Capture(string path){Native.GetWindowThreadProcessId(window,out var targetPid);Native.GetWindowThreadProcessId(Native.GetForegroundWindow(),out var foregroundPid);if(targetPid!=foregroundPid)throw new InvalidOperationException("Capture foreground lost");Native.GetClientRect(window,out var rect);var point=new Native.Point();Native.ClientToScreen(window,ref point);using var bitmap=new System.Drawing.Bitmap(rect.Right,rect.Bottom);using var graphics=System.Drawing.Graphics.FromImage(bitmap);graphics.CopyFromScreen(point.X,point.Y,0,0,bitmap.Size);bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}
 static int Main(string[] args){var runner=args[0];var output=args[1];var renderer=args[2];bool inject=args[3]=="1",startupOnly=args[4]=="1",production=args.Length>5&&args[5]=="1";snapshot=Path.Combine(output,"snapshot.json");Native.SetProcessDpiAwarenessContext(-4);Native.GetCursorPos(out var original);Process? process=null;var report=new Dictionary<string,object?>{{"scope","test-only read-only frame instrumentation + real pointer/keyboard input; NOT UIA, physical paint or comparative timing"},{"requested",renderer},{"injected",inject},{"runnerSha256",Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(runner)))}};int result=1;
  try{var start=new ProcessStartInfo(runner){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(runner)!,CreateNoWindow=true};foreach(var a in new[]{"--renderer",renderer})start.ArgumentList.Add(a);if(!production){start.ArgumentList.Add("--probe");start.ArgumentList.Add(snapshot);}if(inject)start.ArgumentList.Add("--inject-dx12-unavailable");process=Process.Start(start)!;double until=Now()+30000;while((window=Native.Window(process.Id))==0){if(process.HasExited)throw new InvalidOperationException("Early startup exit: "+process.ExitCode);if(Now()>until)throw new TimeoutException("Window");Thread.Sleep(20);}if(!Native.Foreground(window))throw new InvalidOperationException("Foreground");if(production){Thread.Sleep(1000);if(process.HasExited)throw new InvalidOperationException("Production exited early");Capture(Path.Combine(output,"main.png"));report["scope"]="production window startup/drawing/shutdown smoke only; no read-only probe or UIA controls";}else{Wait(_=>Flag("ready"),"Ready");
   report["actualRenderer"]=current.GetProperty("renderer").GetString();report["adapter"]=current.GetProperty("adapter").GetString();report["software"]=Flag("software");report["fallback"]=Flag("fallback");
   if(renderer!="auto"&&current.GetProperty("renderer").GetString()!=renderer.ToUpperInvariant())throw new InvalidOperationException("Wrong explicit renderer");if(inject&&(!Flag("fallback")||current.GetProperty("renderer").GetString()!="DX11"))throw new InvalidOperationException("Fallback not exercised");
   if(!startupOnly){
    Click("About this test");Wait(_=>Flag("about")&&Widget("Close")!=null,"dialog open");Press(27);Wait(_=>!Flag("about"),"Escape");Wait(_=>Widget("About this test")?.GetProperty("focused").GetBoolean()==true,"Escape focus restored");Click("About this test");Wait(_=>Widget("Close")!=null,"dialog reopened");Press(9);Wait(_=>Widget("Close")?.GetProperty("focused").GetBoolean()==true,"modal Tab containment");Click("Close");Wait(_=>!Flag("about"),"Close");Wait(_=>Widget("About this test")?.GetProperty("focused").GetBoolean()==true,"Close focus restored");
    Click("Simulate encryption");Wait(_=>Number("phase")==2&&Number("progress")==100,"complete");Click("Reset");Click("Simulate decryption");Click("Cancel");Wait(_=>Number("phase")==3,"cancel");Click("Reset");
    Click("Open workbench");Wait(_=>current.GetProperty("page").GetString()=="workbench","workbench");Rows(1000,0,0);Click("10,000 rows");Rows(10000,0,1000);Click("1,000 rows");Rows(1000,0,11000);Click("Reverse");Rows(1000,0,11999);Click("Splice 10");Rows(1000,0,12000);Click("Update 10%");Rows(1000,1,12000);Query("row-12000 ");Rows(1,1,12000);Query("");Rows(1000,1);Click("30 Hz / 2 s");Query("row-12000 ");Wait(_=>Number("count")==1&&Number("tick")>1,"live filtering");Click("Stop");Wait(_=>Number("hz")==0,"Stop");Click("Remount workload");Rows(1000,0,0);
    foreach(int hz in new[]{10,60}){Click($"{hz} Hz / 2 s");Wait(_=>Number("tick")>2,"ticks");Click("Stop");Wait(_=>Number("hz")==0,"Stop stable");int tick=Number("tick");Thread.Sleep(250);current=Read();if(Number("tick")!=tick)throw new InvalidOperationException("Stale tick");}
    Query("not-present");Wait(_=>Number("count")==0,"empty filter");Query("");Click("30 Hz / 2 s");Click("Back to main screen");Wait(_=>current.GetProperty("page").GetString()=="main","back");Click("Open workbench");Rows(1000,0,0);Thread.Sleep(250);current=Read();if(Number("tick")!=0)throw new InvalidOperationException("Unmount timer leaked");Click("Back to main screen");Wait(_=>current.GetProperty("page").GetString()=="main","main restored");
    Native.GetClientRect(window,out var c);Native.GetWindowRect(window,out var w);uint dpi=Native.GetDpiForWindow(window);Native.SetWindowPos(window,0,20,20,(int)(w.Right-w.Left+480*dpi/96-c.Right),(int)(w.Bottom-w.Top+640*dpi/96-c.Bottom),0x14);
    Wait(_=>Widget("Simulate decryption") is JsonElement d&&Widget("Simulate encryption") is JsonElement e&&e.GetProperty("y").GetDouble()>=d.GetProperty("y").GetDouble()+d.GetProperty("h").GetDouble(),"480 DIP stacking");Capture(Path.Combine(output,"narrow.png"));Native.GetClientRect(window,out c);Native.GetWindowRect(window,out w);Native.SetWindowPos(window,0,20,20,(int)(w.Right-w.Left+960*dpi/96-c.Right),(int)(w.Bottom-w.Top+640*dpi/96-c.Bottom),0x14);Thread.Sleep(200);Capture(Path.Combine(output,"main.png"));
   }
   }report["status"]="passed";result=0;
  }catch(Exception e){report["status"]="failed";report["error"]=e.ToString();if(current.ValueKind==JsonValueKind.Object)report["lastSnapshot"]=current;}
  finally{if(window!=0&&process!=null&&!process.HasExited&&Native.GetWindowThreadProcessId(window,out var owner)!=0&&owner==process.Id)Native.PostMessageW(window,0x10,0,0);if(process!=null){bool exited=process.WaitForExit(15000);report["exitedNormally"]=exited&&process.ExitCode==0;report["exitCode"]=exited?process.ExitCode:null;if(!exited){process.Kill();process.WaitForExit();}if(!exited||process.ExitCode!=0){result=1;report["status"]="failed";}process.Dispose();}report["checks"]=passed;File.WriteAllText(Path.Combine(output,"result.json"),JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Native.SetCursorPos(original.X,original.Y);}
  Console.WriteLine(JsonSerializer.Serialize(new{status=report["status"],output}));return result;
 }
